interface Sensor {
    fun read(): Double
}

class DistanceSensor(val distance: Double) : Sensor {
    override fun read(): Double {
        return distance
    }
}

class TemperatureSensor(val temp: Double) : Sensor {
    override fun read(): Double {
        return temp
    }
}

