import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testDistanceSensor() {
        val sensor = DistanceSensor(42.5)
        Assert.assertEquals(42.5, sensor.read(), 0.001)
    }

    @Test
    fun testTemperatureSensor() {
        val sensor = TemperatureSensor(98.6)
        Assert.assertEquals(98.6, sensor.read(), 0.001)
    }

    @Test
    fun testDistanceIsSensor() {
        val sensor = DistanceSensor(10.0)
        Assert.assertTrue(sensor is Sensor)
    }

    @Test
    fun testTemperatureIsSensor() {
        val sensor = TemperatureSensor(72.0)
        Assert.assertTrue(sensor is Sensor)
    }

    @Test
    fun testPolymorphicList() {
        val sensors: List<Sensor> = listOf(DistanceSensor(5.0), TemperatureSensor(100.0))
        Assert.assertEquals(5.0, sensors[0].read(), 0.001)
        Assert.assertEquals(100.0, sensors[1].read(), 0.001)
    }
}
